records=[]
for m in catalog['methods']:
 rid=m['method_id']
 if rid not in gaps:continue
 doc=ROOT/m['research_document'];src=ROOT/m['source_claims'];t=doc.read_text();claims=json.loads(src.read_text());g,fix,external=gaps[rid]
 record={'method_id':rid,'name':m['name'],'baseline_package':m['preferred_authored_path'],'baseline_document':m['research_document'],'baseline_document_sha256':hashlib.sha256(doc.read_bytes()).hexdigest(),'baseline_manifest_sha256':m['preferred_manifest_sha256'],'evidence_locations':[{'path':m['research_document'],'locator':'全文，含模型/例与边界说明','actual_read':True},{'path':m['source_claims'],'locator':'selected read/scope/claim fields','actual_read':True},{'path':m['teaching_artifacts_directory'],'locator':'existing fixed input/intermediate/output archive, not new field evidence'}],'substantive_gap':g,'work_items':[{'type':'可直接修','action':fix},{'type':'继续检索','action':'围绕上述缺口补一手方法段落；原书/公式缺失不凭二手推断'},{'type':'需现实输入','action':external,'blocks':'真实设备/客户/专业结论；不阻止受限方法教学'}],'priority':'P0'if rid in['R38','R49','R52']else'P1','seven_dimensions_baseline':{k:{'rating':'充分'if k=='身份与边界准确'else'局部','evidence':m['research_document']+'；'+m['source_claims'],'reason':'现有范围标识清楚；完整操作/推理与反例需按本项实质缺口继续展开'if k=='身份与边界准确'else g}for k in ['身份与边界准确','机制讲透','判断可操作','完整示范','反例与迁移','依据可追溯','阅读与交接']},'assessment_identity':'authoring-agent qualitative baseline audit, not calibrated score or approval','candidate_status':'rewrite_pending_independent_content_review'}
 records.append(record)
assert len(records)==21
(D/'质量缺口台账.json').write_text(json.dumps({'version':'0.1.0','date':'2026-10-28','scope':'21 method bodies, not test/field count assessment','priority_first_three':['R38','R49','R52'],'methods':records},ensure_ascii=False,indent=2))
